#include "original_q7_helpers.inc"
#include "ui/kasane/ksn_mesh_q7_certified.h"
extern const ksn_mesh_q7_snapshot *pocket_proc_q7_host_snapshot(unsigned,bool);
int main(void){
 JSRuntime*rt=JS_NewRuntime();REQUIRE(rt);JSContext*ctx=JS_NewContext(rt);REQUIRE(ctx);JSValue g=JS_GetGlobalObject(ctx),p=JS_NewObject(ctx);REQUIRE(pocket_shiki_api_install(ctx,p)==ESP_OK);REQUIRE(JS_SetPropertyStr(ctx,g,"K",p)>=0);JS_FreeValue(ctx,g);eval_ok(ctx,"globalThis.P=K.shiki;globalThis.pocket={kasane:K}");
 ksn_proc_gouraud_patch red=triangle(63488),blue=triangle(31);float z[3]={0,0,0};
 // Fail each first-time derived allocation; valid packet rendering still succeeds.
 for(int fail=0;fail<3;fail++){pocket_proc_reset();eval_ok(ctx,"P.beginMeshFrame(0,65536,8000000,1)");append(ctx,&red,z);pocket_proc_mesh_fail_after(fail);eval_ok(ctx,"P.commit()");pocket_proc_mesh_fail_after(-1);REQUIRE(pocket_proc_backdrop(NULL,0,135,actual)==KSN_OK&&actual[2892]==63488);pocket_proc_present_result(KSN_OK);}
 pocket_proc_reset();eval_ok(ctx,"P.beginMeshFrame(0,65536,8000000,8)");append(ctx,&red,z);eval_ok(ctx,"P.commit()");REQUIRE(pocket_proc_q7_host_snapshot(0,false)&&pocket_proc_q7_host_snapshot(0,false)->valid);pocket_proc_present_result(KSN_OK);
 const ksn_mesh_q7_snapshot*committed=pocket_proc_q7_host_snapshot(0,true);size_t committed_bytes=sizeof(*committed)+committed->count*sizeof committed->triangles[0];unsigned char*saved=malloc(committed_bytes);REQUIRE(saved);memcpy(saved,committed,committed_bytes);
 for(int fail=0;fail<3;fail++){eval_ok(ctx,"P.beginMeshFrame(0,65536,8000000,1)");append(ctx,&blue,z);pocket_proc_mesh_fail_after(fail);eval_ok(ctx,"P.commit()");pocket_proc_mesh_fail_after(-1);REQUIRE(pocket_proc_q7_host_snapshot(0,true)==committed&&!memcmp(saved,committed,committed_bytes));REQUIRE(pocket_proc_backdrop(NULL,0,135,actual)==KSN_OK&&actual[2892]==31);pocket_proc_present_result(KSN_IO);REQUIRE(pocket_proc_backdrop(NULL,0,135,actual)==KSN_OK&&actual[2892]==63488);REQUIRE(!memcmp(saved,committed,committed_bytes));eval_error(ctx,"P.beginFrame(0)");pocket_proc_present_result(KSN_OK);REQUIRE(pocket_proc_q7_host_snapshot(0,true)==committed);}
 // Count64 fits;65 faces must use original/retained admission fallback without dropping last.
 eval_ok(ctx,"P.beginMeshFrame(0,65536,8000000,8)");for(unsigned i=0;i<64;i++)append(ctx,&red,z);eval_ok(ctx,"P.commit()");REQUIRE(pocket_proc_q7_host_snapshot(0,false)->count==64);pocket_proc_present_result(KSN_IO);pocket_proc_present_result(KSN_OK);
 eval_ok(ctx,"P.beginMeshFrame(0,65536,8000000,8)");for(unsigned i=0;i<64;i++)append(ctx,&red,z);z[0]=z[1]=z[2]=1;append(ctx,&blue,z);eval_ok(ctx,"P.commit()");REQUIRE(!pocket_proc_q7_host_snapshot(0,false)->valid);REQUIRE(pocket_proc_backdrop(NULL,0,135,actual)==KSN_OK&&actual[2892]==31);pocket_proc_present_result(KSN_IO);pocket_proc_present_result(KSN_OK);REQUIRE(!memcmp(saved,committed,committed_bytes));free(saved);
 // Image IO keeps the submitted candidate intact until its eventual ACK.
 pocket_proc_image_mode();eval_ok(ctx,"P.beginMeshFrame(0,65536,8000000,1)");append(ctx,&blue,z);eval_ok(ctx,"P.commit()");const ksn_mesh_q7_snapshot*candidate=pocket_proc_q7_host_snapshot(0,false);REQUIRE(candidate&&candidate->valid&&candidate->count==1);pocket_proc_present_result(KSN_IO);REQUIRE(pocket_proc_pending()&&pocket_proc_q7_host_snapshot(0,false)==candidate);eval_error(ctx,"P.beginFrame(0)");ksn_image_port port;pocket_proc_image_port(&port);REQUIRE(pocket_proc_backdrop(NULL,0,135,expected)==KSN_OK);for(unsigned y=0;y<135;y+=4){unsigned n=135-y;if(n>4)n=4;REQUIRE(port.read_rows(port.ctx,0,0,y,n,0,240,actual+y*240,240)==KSN_OK);}REQUIRE(!memcmp(actual,expected,sizeof actual));pocket_proc_present_result(KSN_OK);REQUIRE(pocket_proc_q7_host_snapshot(0,true)==candidate&&!pocket_proc_pending());
 pocket_proc_mesh_bytes bytes;pocket_proc_mesh_memory(&bytes);printf("Q7_LIFECYCLE_PASS initial_OOM3 committed_immutable OOM_backdrop_repair count64 face65_fallback image_retry_ACK metadata=%zu workspace=%zu\n",bytes.metadata,bytes.workspace);pocket_proc_reset();pocket_proc_mesh_memory(&bytes);REQUIRE(!bytes.candidate&&!bytes.committed&&!bytes.workspace);REQUIRE(!pocket_proc_q7_host_snapshot(0,true)&&!pocket_proc_q7_host_snapshot(0,false));JS_FreeContext(ctx);JS_FreeRuntime(rt);return 0;
}
